        int len = r.nextInt(minLen, maxLen);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++) {
            sb.append(ALPHABET.charAt(r.nextInt(0, ALPHABET.length() - 1)));
        }
