            if (r.nextInt(0, 19) == 0) return null;
            String[] arr = new String[randomLength(r)];
            for (int i = 0; i < arr.length; i++) {
                int k = r.nextInt(0, 9);
                if (k < 4) arr[i] = null;
                else if (k == 4) arr[i] = "";
                else arr[i] = randomWord(r, 1, 4);
            }
            return arr;
        }
    }

