            }
        }
        return hasNullReplacement && hasActiveMatch;
    }

    @Fuzz
    public void testBugReproduction(@From(TextGen.class) String text,
                                    @From(SearchGen.class) String[] searchList,
                                    @From(ReplacementGen.class) String[] replacementList) {
